// CTS Business Intelligence Portal - brand assets
//
// The official CTS Seamless AV palette, from cts_pantonevalues.pdf via the
// CTS slide template work, and the logos inlined so they travel with the
// portal. The brand guidelines say the logo always appears locked up with
// the promise "Seamless AV". Tomato Grotesk is the brand face; the portal
// uses Sora and Figtree from Google Fonts as the closest faces it can load,
// with Segoe UI and Calibri behind them.
//
// Sub brands and their colours:
//   Production  mint #3FD0C9 (PMS 3255 C), dark teal #005358 (PMS 7476 C)
//   Consulting  lavender #6D71FF (PMS 2124 C), dark navy #122B82 (PMS 287 C)
//   Support     rose #F33844 (PMS 1788 C), dark burgundy #A8052E (PMS 1945 C)
//   Base        black #121820 (PMS Black 6 C)
// Mint, lavender and rose are for fills, blocks and charts. The dark variants
// or black are for text on white: the light colours fail contrast as small
// text. Chart series use these hues snapped into the lightness band the
// colour vision checks need; the exact values are in the portal stylesheet.
window.CTS_BRAND = {
  meta: { source: "cts_pantonevalues.pdf and the CTS website lock-ups, via the CTS Slide Templates canvas", built: "2026-09-25" },
  font: { brand: "Tomato Grotesk", portal: "Sora for headings, Figtree for text", fallback: "Segoe UI, Calibri" },
  palette: {
    base: "#121820", white: "#FFFFFF", grey: "#5F6670", greyLight: "#C9CED6", panel: "#F6F7F9",
    production: { light: "#3FD0C9", dark: "#005358", tint: "#E8F9F8", pms: ["3255 C", "7476 C"] },
    consulting: { light: "#6D71FF", dark: "#122B82", tint: "#EEEEFF", pms: ["2124 C", "287 C"] },
    support:    { light: "#F33844", dark: "#A8052E", tint: "#FEEBEC", pms: ["1788 C", "1945 C"] },
  },
  // which sub brand each portal department belongs to, for colour and marks
  subBrandOf: { ONSITE: "support", PRODUCTION: "production", VIDEO: "production", INTEGRATION: "consulting", CONSULTING: "consulting", ADMIN: "base" },
  logo: { alt: "cts Seamless AV", light: "data:image/png;base64,", dark: "data:image/png;base64," },
  marks: {
    production: { alt: "CTS Production", onDark: "data:image/png;base64," },
    consulting: { alt: "CTS Consulting", onDark: "data:image/png;base64," },
    support:    { alt: "CTS Support",    onDark: "data:image/png;base64," },
    twenty:     { alt: "CTS 20 years",   onDark: "data:image/png;base64," },
  },
};
